<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Merchant/spread_higher_merchant',array('mer_id'=>$_GET['mer_id']))}" class="on">【{pigcms{$merchant_info['name']}】上级推广商家列表</a>				</ul>			</div>							<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col> <col><col><col><col><col><col width="240" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>												<th>商家名称</th>								<if condition="!isset($config['not_o2o_demo'])">								<th>联系电话</th>								</if>                                <th>商家获得佣金</th>							</tr>						</thead>						<tbody>							<if condition="is_array($merchant_list)">								<volist name="merchant_list" id="vo">									<tr>										<td>{pigcms{$vo.mer_id}</td>																		<td>{pigcms{$vo.name}</td>										<if condition="!isset($config['not_o2o_demo'])">										<td>{pigcms{$vo.phone}</td>										</if>                                        <td>{pigcms{$vo.all_spread_money}</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>				</div><script>   var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('Merchant/export_info')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>